-- Creature and gameobject data from the earlier Keira3 based generator, not regenerated yet.
-- The spell editor data lives in Spell*.lua, generated by HoT/Editor/DataGen/gen.py.
GameEditorData = GameEditorData or {}

-- Fields[table][column] = {label, tooltip, type, enum or flags, ...}
--   flagsBy = {column, prefix}: the flags table name is prefix .. value of that column
--   ref = linked table (dbc:Name for client tables)
-- Columns[table] = column order as in the DB or the DBC binding.

GameEditorData.Fields = GameEditorData.Fields or {}
GameEditorData.Columns = GameEditorData.Columns or {}

