        [46] = {name = "AREATRIGGER_ONTRIGGER", tooltip = "On areatrigger reached by a player", params = {{name = "AreatriggerId", tooltip = "Entry of the areatrigger to make this event happen. If left at 0, it will trigger for ANY areatrigger"}}, core = "TriggerId(0 any)"},
        [47] = {name = "QUEST_ACCEPTED", tooltip = "When the quest is accepted. Only for Quest scripts (source_type 9)", core = "none"},
        [48] = {name = "QUEST_OBJ_COMPLETION", tooltip = "When all objectives of the quest are completed. Only for Quest scripts (source_type 9)", core = "none"},
