        [51] = {name = "QUEST_FAIL", tooltip = "When the quest is failed. Only for Quest scripts (source_type 9)", core = "none"},
        [52] = {name = "TEXT_OVER", tooltip = "When a creature says something it shows a balloon for a few seconds. This event is triggered after the balloon fades and thus the text \"finishes\". Event Triggered After SMART_ACTION_TALK", params = {{name = "GroupID", tooltip = "The creature_text.GroupID value to trigger this event for"}, {name = "CreatureId", tooltip = "Use 0 for ANY creature"}}, core = "GroupId from creature_text, creature entry who talks (0 any)"},
        [53] = {name = "RECEIVE_HEAL", tooltip = "On creature received a certain heal amount", params = {{name = "MinHeal", tooltip = "Minimum required value the heal effect must be in order to trigger this event"}, {name = "MaxHeal", tooltip = "Maximum allowed value of the heal effect to allow this event to trigger"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "MinHeal, MaxHeal, CooldownMin, CooldownMax"},
        [54] = {name = "JUST_SUMMONED", tooltip = "On Creature just spawned (Use 63|JUST_CREATED for objects)", core = "none"},
        [55] = {name = "WAYPOINT_PAUSED", tooltip = "On Creature Paused at Waypoint ID", params = {{name = "PointId", tooltip = "Use 0 for ANY point"}, {name = "PathId", tooltip = "Use 0 for ANY path"}}, core = "PointId(0any), pathID(0any)"},
        [56] = {name = "WAYPOINT_RESUMED", tooltip = "On Creature Resumed after Waypoint ID", params = {{name = "PointId", tooltip = "Use 0 for ANY point"}, {name = "PathId", tooltip = "Use 0 for ANY path"}}, core = "PointId(0any), pathID(0any)"},
        [57] = {name = "WAYPOINT_STOPPED", tooltip = "On Creature Stopped On Waypoint ID", params = {{name = "PointId", tooltip = "Use 0 for ANY point"}, {name = "PathId", tooltip = "Use 0 for ANY path"}}, core = "PointId(0any), pathID(0any)"},
        [58] = {name = "WAYPOINT_ENDED", tooltip = "On Creature Waypoint Path Ended", params = {{name = "PointId", tooltip = "Use 0 for ANY point"}, {name = "PathId", tooltip = "Use 0 for ANY path"}}, core = "PointId(0any), pathID(0any)"},
        [59] = {name = "TIMED_EVENT_TRIGGERED", tooltip = "Called when a timed event called by the action CREATE_TIMED_EVENT is triggered", params = {{name = "EventId", tooltip = "First parameter of SMART_ACTION_CREATE_TIMED_EVENT"}}, core = "id"},
        [60] = {name = "UPDATE", tooltip = "On update, should be used as a timer. Basically functions like both UPDATE_IC and UPDATE_OOC in one.", params = {{name = "InitialMin"}, {name = "InitialMax"}, {name = "RepeatMin"}, {name = "RepeatMax"}}, core = "InitialMin, InitialMax, RepeatMin, RepeatMax"},
        [61] = {name = "LINK", tooltip = "Used to link together multiple events as a chain of events.", core = "INTERNAL USAGE, no params, used to link together multiple events, does not use any extra resources to iterate event lists needlessly"},
        [62] = {name = "GOSSIP_SELECT", tooltip = "Called on gossip option selected. Imagine you have four gossip items under the menu id 5 and their id's are 0, 1 and 2. If you now call this event with first parameter '5' and second parameter '1', it will be called when the second gossip option is selected. Tables `gossip_menu_option` and `gossip_menu.`", params = {{name = "Gossip MenuID", tooltip = "This is gossip_menu_option.MenuID"}, {name = "Gossip OptionID", tooltip = "gossip_menu_option.OptionID"}}, core = "menuID, actionID"},
        [63] = {name = "JUST_CREATED", tooltip = "On Gameobject just spawned/created (Use 54|JUST_SUMMONED for creatures)", core = "none"},
        [64] = {name = "GOSSIP_HELLO", tooltip = "On Right-Click Creature/Gameobject that have gossip enabled.", params = {{name = "filter", tooltip = "This is gossipHello.filter0=no filter set, always execute action. 1=GossipHello only filter set, skip action if reportUse. 2=reportUse only filter set, skip action if GossipHello."}}, core = "noReportUse (for GOs)"},
        [65] = {name = "FOLLOW_COMPLETED", tooltip = "On follow completed/finished", core = "none"},
        [66] = {name = "EVENT_PHASE_CHANGE", core = "UNUSED, DO NOT REUSE"},
        [67] = {name = "IS_BEHIND_TARGET", core = "UNUSED, DO NOT REUSE"},
        [68] = {name = "GAME_EVENT_START", tooltip = "On game event just started", params = {{name = "EventID", tooltip = "game_event.eventEntryThis is game_event.eventEntry"}}, core = "game_event.Entry"},
        [69] = {name = "GAME_EVENT_END", tooltip = "On game event just ended", params = {{name = "EventID", tooltip = "This is game_event.eventEntry"}}},
        [70] = {name = "GO_LOOT_STATE_CHANGED", tooltip = "On gameobject state changed.", params = {{name = "State", tooltip = "0 = Active. 1 = Ready. 2 = Active alternative"}}, core = "go LootState"},
        [71] = {name = "GO_EVENT_INFORM", tooltip = "Called when the gameobject becomes the target of an event happening. This is called in cases like a building is damaged/destroyed/rebuild, a goober is used, etc.", params = {{name = "EventId"}}, core = "eventId"},
        [72] = {name = "ACTION_DONE", tooltip = "Called on a certain action id 'done'. Those can only be called from base-abstract-classes scripts (SmartAI::DoAction).", params = {{name = "ActionId"}}, core = "eventId (SharedDefines.EventId)"},
        [73] = {name = "ON_SPELLCLICK", tooltip = "On unit spellclick. For more information on what spellclicks are, take a look at the wiki and search for the table 'npc_spellclick_spells' (world database).", core = "clicker (unit)"},
        [74] = {name = "FRIENDLY_HEALTH_PCT", tooltip = "When a friendly unit within a certain range reaches a certain health percentage (so NOT flat health!). If you are looking for a flat modifier, use event type 14.", params = {{name = "InitialMin", tooltip = "ms"}, {name = "InitialMax", tooltip = "ms"}, {name = "RepeatMin", tooltip = "ms"}, {name = "RepeatMax", tooltip = "ms"}, {name = "HP%", tooltip = "HP Percentage required to fire event"}}, core = "minHpPct, maxHpPct, repeatMin, repeatMax"},
        [75] = {name = "DISTANCE_CREATURE", tooltip = "On creature guid OR any instance of creature entry is within distance.", params = {{name = "Guid", tooltip = "Guid of the creature we want to check for. Can be left on 0 if the Entry is given."}, {name = "Entry", tooltip = "Entry of the creature we want to check for. Can be left on 0 if the Guid is given."}, {name = "Distance", tooltip = "Min distance (in yards) to the creature that will trigger the event"}, {name = "RepeatTimer", tooltip = "Timer to check for distance. It's not a good idea to leave this at 0, having a handful of events doing that can slow down your base-abstract-classes"}}, core = "guid, entry, distance, repeat"},
        [76] = {name = "DISTANCE_GAMEOBJECT", tooltip = "On gameobject guid OR any instance of gameobject entry is within distance.", params = {{name = "Guid", tooltip = "Guid of the gameobject we want to check for. Can be left on 0 if the entry is given."}, {name = "Entry", tooltip = "Entry of the gameobject we want to check for. Can be left on 0 if the guid is given."}, {name = "Distance", tooltip = "Min distance (in yards) to the gameobject that will trigger the event"}, {name = "RepeatTimer", tooltip = "Timer to check for distance. It's not a good idea to leave this at 0, having a handful of events doing that can slow down your base-abstract-classes"}}, core = "guid, entry, distance, repeat"},
        [77] = {name = "COUNTER_SET", tooltip = "If the value of specified CounterID is equal to a specified Value.", params = {{name = "CounterID"}, {name = "Value"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "id, value, cooldownMin, cooldownMax"},
        [78] = {name = "SCENE_START", core = "don't use on 3.3.5a"},
        [79] = {name = "SCENE_TRIGGER", core = "don't use on 3.3.5a"},
        [80] = {name = "SCENE_CANCEL", core = "don't use on 3.3.5a"},
        [81] = {name = "SCENE_COMPLETE", core = "don't use on 3.3.5a"},
        [82] = {name = "SUMMONED_UNIT_DIES", tooltip = "When specified summoned creature (or 0, for all) dies.", params = {{name = "CreatureId", tooltip = "0 for all"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "CreatureId(0 all), CooldownMin, CooldownMax"},
        [83] = {name = "ON_SPELL_CAST", tooltip = "When the creature successfully finishes casting a spell", params = {{name = "SpellID"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "SpellID, CooldownMin, CooldownMax"},
        [84] = {name = "ON_SPELL_FAILED", tooltip = "When the creature fails to cast a spell", params = {{name = "SpellID"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "SpellID, CooldownMin, CooldownMax"},
        [85] = {name = "ON_SPELL_START", tooltip = "When the creature starts casting a spell", params = {{name = "SpellID"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "SpellID, CooldownMin, CooldownMax"},
        [86] = {name = "ON_DESPAWN", tooltip = "When the creature despawns", core = "NONE"},
        [87] = {name = "SEND_EVENT_TRIGGER", core = "UNUSED NEEDS CHERRYPICK"},
        [88] = {name = "AREATRIGGER_EXIT", core = "don't use on 3.3.5a"},
        [89] = {name = "ON_AURA_APPLIED", tooltip = "When an aura is applied to the creature", params = {{name = "SpellID"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "SpellID, CooldownMin, CooldownMax"},
        [90] = {name = "ON_AURA_REMOVED", tooltip = "When an aura is removed from the creature", params = {{name = "SpellID"}, {name = "CooldownMin"}, {name = "CooldownMax"}}, core = "SpellID, CooldownMin, CooldownMax"},
    },
    Action = {
        [0] = {name = "NONE", tooltip = "No action type is specified. Do not use because it will cause errors on start-up.", core = "No action"},
        [1] = {name = "TALK", tooltip = "Creature says a creature_text line", params = {{name = "GroupId", tooltip = "This is creature_text.GroupID"}, {name = "Duration", tooltip = "Duration (milliseconds) to wait before SMART_EVENT_TEXT_OVER event is triggered"}, {name = "Target", tooltip = "0 = Try to trigger talk of the target. 1 = Set target as talk target (used for $vars in texts and whisper target)"}, {name = "Delay", tooltip = "Duration (milliseconds) to delay the Action"}}, core = "groupID from creature_text, duration to wait before TEXT_OVER event is triggered, useTalkTarget (0/1) - use target as talk target"},
        [2] = {name = "SET_FACTION", tooltip = "Set faction of target", params = {{name = "FactionId"}}, core = "FactionId (or 0 for default)"},
        [3] = {name = "MORPH_TO_ENTRY_OR_MODEL", tooltip = "Morph the creature to a CreatureId (by taking its model) or a given ModelId. If both parameters are 0, demorph the creature", params = {{name = "CreatureId"}, {name = "ModelId"}}, core = "Creature_template entry(param1) OR ModelId (param2) (or 0 for both to demorph)"},
        [4] = {name = "SOUND", tooltip = "Play a sound", params = {{name = "SoundId"}, {name = "OnlySelf", tooltip = "0 = sends sound to everyone in visibility range. 1 = sends sound to self"}, {name = "Distance", tooltip = "0 or 1 - determines whether or not to play the sound from distance"}}, core = "SoundId, onlySelf"},
        [5] = {name = "PLAY_EMOTE", tooltip = "Play en emote", params = {{name = "EmoteId"}}, core = "EmoteId"},
        [6] = {name = "FAIL_QUEST", tooltip = "Set a certain quest of our (player) target to 'fail', making them have to re-take it", params = {{name = "QuestId"}}, core = "QuestID"},
        [7] = {name = "OFFER_QUEST", tooltip = "Add a quest to our (player) target's quest list", params = {{name = "QuestId"}, {name = "directAdd", tooltip = "0 or 1"}}, core = "QuestID, directAdd"},
        [8] = {name = "SET_REACT_STATE", tooltip = "ReactState. Can be Passive (0), Defensive (1), Aggressive (2).", params = {{name = "ReactState", tooltip = "0 = Passive. 1 = Defensive. 2 = Aggressive"}}, core = "state"},
        [9] = {name = "ACTIVATE_GOBJECT", tooltip = "Activate a gameobject (targets our target_type, so it must be a gameobject)"},
        [10] = {name = "RANDOM_EMOTE", tooltip = "Play a random emote. Out of a total of 6 parameters it will pick one and ignore all fields with the value 0", params = {{name = "EmoteId1"}, {name = "EmoteId2"}, {name = "EmoteId3"}, {name = "EmoteId4"}, {name = "EmoteId5"}, {name = "EmoteId6"}}, core = "EmoteId1, EmoteId2, EmoteId3..."},
        [11] = {name = "CAST", tooltip = "Cast a spell to our target type", params = {{name = "SpellId"}, {name = "CastFlags", tooltip = "Cannot be 0"}, {name = "TriggerFlags", tooltip = "0 = Not triggered"}, {name = "LimitTargets", tooltip = "0 = all targets"}}, core = "SpellId, CastFlags, TriggeredFlags"},
        [12] = {name = "SUMMON_CREATURE", tooltip = "Summons a creature for a given time (or permanent, depending on the summon type which is set in the second parameter)", params = {{name = "CreatureId"}, {name = "SummonType", tooltip = "1 - Despawns after a specified time OR when the creature disappears. 2 - Despawns after a specified time OR when the creature dies. 3 - Despawns after a specified time. 4 - Despawns after a specified time after the creature is out of combat. 5 - Despawns instantly after death. 6 - Despawns after a specified time after death. 7 - Despawns when the creature disappears. 8 - Despawns when UnSummon() (or Force Despawn action) is called."}, {name = "Duration", tooltip = "Duration (milliseconds)"}, {name = "AttackInvoker", tooltip = "Whether or not the summoned creature should attack the action invoker (SMART_TARGET_ACTION_INVOKER) when it's summoned. 0: it will not attack. 1: attack target. 2: attack actual invoker"}, {name = "AttackScriptOwner", tooltip = "0 = it will not attack, 1 = it will attack"}}, core = "CreatureID, summonType, duration in ms, attackInvoker, flags(SmartActionSummonCreatureFlags)"},
        [13] = {name = "THREAT_SINGLE_PCT", tooltip = "Add or remove a certain percentage of threat from our current threat. Only one of the parameters (so either 1 or 2) may be used at the same time", params = {{name = "ThreatIncrease%"}, {name = "ThreatDecrease%"}}, core = "Threat%"},
        [14] = {name = "THREAT_ALL_PCT", tooltip = "Add or remove a certain percentage of threat from our current threat. Only one of the parameters (so either 1 or 2) may be used at the same time", params = {{name = "ThreatIncrease%"}, {name = "ThreatDecrease%"}}, core = "Threat%"},
        [15] = {name = "CALL_AREAEXPLOREDOREVENTHAPPENS", tooltip = "Complete a quest requirement (by entry) of our current (player) target", params = {{name = "QuestId"}}, core = "QuestID"},
        [16] = {name = "RESERVED_16", core = "used on 4.3.4 and higher scripts"},
        [17] = {name = "SET_EMOTE_STATE", tooltip = "Set emote state", params = {{name = "EmoteId"}}, core = "emoteID"},
        [18] = {name = "SET_UNIT_FLAG", core = "UNUSED, DO NOT REUSE"},
        [19] = {name = "REMOVE_UNIT_FLAG", core = "UNUSED, DO NOT REUSE"},
        [20] = {name = "AUTO_ATTACK", tooltip = "Stop or Continue Automatic Attack.", params = {{name = "AllowAttackState", tooltip = "0 = disable auto attack, the creature will stop attacking its current target. 1 = allow the creature to attack its target"}}, core = "AllowAttackState (0 = stop attack, anything else means continue attacking)"},
        [21] = {name = "ALLOW_COMBAT_MOVEMENT", tooltip = "Allow or disallow moving while the creature is in combat", params = {{name = "Allow", tooltip = "0 = the creature is no longer able to move AT ALL during combat. 1 = it's allowed to normally walk during combat"}}, core = "AllowCombatMovement (0 = stop combat based movement, anything else continue attacking)"},
        [22] = {name = "SET_EVENT_PHASE", tooltip = "Set the creature's event phase to a new value (warning: this is NOT the creature's actual phase!)", params = {{name = "EventPhase", tooltip = "Event phase 0-12 (the actual values, no bit mask!)"}}, core = "Phase"},
        [23] = {name = "INC_EVENT_PHASE", tooltip = "Increment or decrement the creature's event phasemask (warning: this is NOT the creature's actual phase!)", params = {{name = "Increment"}, {name = "Decrement"}}, core = "Value (may be negative to decrement phase, should not be 0)"},
        [24] = {name = "EVADE", tooltip = "Makes the creature evade and therefore make it stop attacking and leave combat.", core = "toRespawnPosition (0 = Move to RespawnPosition, 1 = Move to last stored home position)"},
        [25] = {name = "FLEE_FOR_ASSIST", tooltip = "Makes the creature flee for assistance of nearby friendly units", params = {{name = "SayFleeText", tooltip = "0 or 1 - determines whether or not the creature should say something along the lines of \"NAME starts fleeing ...\" when it flees"}}, core = "With Emote"},
        [26] = {name = "CALL_GROUPEVENTHAPPENS", tooltip = "Complete a quest requirement (by entry) of our current (player) target.", params = {{name = "QuestId"}}, core = "QuestID"},
        [27] = {name = "COMBAT_STOP", tooltip = "Complete a quest requirement (by entry) of our current (player) target. Completes a killed monster credit as well as gives credit for a spellcast.", params = {{name = "CreatureId"}, {name = "SpellId"}}},
        [28] = {name = "REMOVEAURASFROMSPELL", tooltip = "Remove an aura/spell from our target", params = {{name = "SpellId", tooltip = "If 0, removes all auras"}, {name = "Charges", tooltip = "Amount of charges of said aura to be removed. If 0, the whole aura is removed."}}, core = "Spellid (0 removes all auras), charges (0 removes aura)"},
        [29] = {name = "FOLLOW", tooltip = "Makes the creature follow the target at a certain distance and with a certain angle.", params = {{name = "Distance"}, {name = "Angle"}, {name = "EndCreatureId", tooltip = "Default is 0. When not 0, the follow will finish ONLY once the creature is within interaction distance (5 yards) of the given entry."}, {name = "Credit", tooltip = "When set, grants quest credit when the follow completes. If CreditType = 0 the value is treated as a creature entry (monster kill credit) and will give kill credit to the player/group. If CreditType = 1 the value is treated as an event id and will trigger the group event for credit."}, {name = "CreditType", tooltip = "Determines how the value in parameter 4 is interpreted. 0 = monster kill credit (calls RewardPlayerAndGroupAtEvent), 1 = event credit (calls GroupEventHappens)."}, {name = "AliveState", tooltip = "Controls whether the creature must be alive to count as arrived. 0 = creature must be alive, 1 = creature can be dead and still count as arrived."}}, core = "Distance (0 = default), Angle (0 = default), EndCreatureEntry, credit, creditType (0monsterkill, 1event)"},
        [30] = {name = "RANDOM_PHASE", tooltip = "Set the creature's event phase (note: this is NOT the creature's actual phase!)", params = {{name = "Phasemask 1"}, {name = "Phasemask 2"}, {name = "Phasemask 3"}, {name = "Phasemask 4"}, {name = "Phasemask 5"}, {name = "Phasemask 6"}}, core = "PhaseId1, PhaseId2, PhaseId3..."},
        [31] = {name = "RANDOM_PHASE_RANGE", tooltip = "Set the creature's event phase randomly between two values (this is NOT the creature's actual phase!)", params = {{name = "PhasemaskMin"}, {name = "PhasemaskMax"}}, core = "PhaseMin, PhaseMax"},
        [32] = {name = "RESET_GOBJECT", tooltip = "Reset a gameobject, usually used to open/close a door (calls GameObject::ResetDoorOrButton)"},
        [33] = {name = "CALL_KILLEDMONSTER", tooltip = "Gives a kill credit to our (player) target. The entry is the same entry as quest_template.RequiredNpcOrGo(1/2/3/4).", params = {{name = "CreatureId"}}, core = "CreatureId"},
        [34] = {name = "SET_INST_DATA", tooltip = "Calls InstanceScript::SetData(field, data) or InstanceScript::SetBossState(field, EncounterState(data)) depending on type.", params = {{name = "Field", tooltip = "Instance data field id"}, {name = "Data", tooltip = "Value to set. If type is 1, this value is cast to `EncounterState`."}, {name = "Type", tooltip = "0 = call SetData(field, data). 1 = call SetBossState(field, EncounterState(data))"}}, core = "Field, Data, Type (0 = SetData, 1 = SetBossState)"},
        [35] = {name = "SET_INST_DATA64", tooltip = "Calls SetGuidData(field, guid) using the GUID from the first action target.", params = {{name = "Field", tooltip = "Instance data field id"}, {tooltip = "The GUID is taken from the first action target."}}, core = "Field"},
        [36] = {name = "UPDATE_TEMPLATE", tooltip = "Updates the creature's entry to a new one, making it become a completely different unit.", params = {{name = "CreatureId", tooltip = "The creature entry we want to become (creature_template.entry)"}, {name = "UpdateLevel"}}, core = "Entry"},
        [37] = {name = "DIE", tooltip = "Kills the target.", params = {{name = "Kill Timer", tooltip = "Time in milliseconds after which the creature kills itself. Leave as 0 to kill it instantly."}}, core = "No Params"},
        [38] = {name = "SET_IN_COMBAT_WITH_ZONE", tooltip = "Sets the creature in combat with its zone, can be used in instances and open world. Useful for creatures inside instances so all players will be set in combat until the fight ends. It only sets NPCs in combat with players, this only works with the target_type 9 - CREATURE_RANGE", core = "No Params"},
        [39] = {name = "CALL_FOR_HELP", tooltip = "Makes the creature cry/call for help, which makes nearby creatures that are not yet in combat and are able to assist this creature, run to this creature and attack its attackers.", params = {{name = "Radius", tooltip = "Radius in yards that other creatures must be to acknowledge the cry for help"}, {name = "SayText", tooltip = "0 or 1: whether or not we should automatically make the creature emote \"NAME calls for help!\""}}, core = "Radius, With Emote"},
        [40] = {name = "SET_SHEATH", tooltip = "Set the sheathe state of the creature. The sheath state determines which weapon will be displayed on the model.", params = {{name = "SheathState", tooltip = "0-unarmed, 1-melee, 2-ranged"}}, core = "Sheath (0-unarmed, 1-melee, 2-ranged)"},
        [41] = {name = "FORCE_DESPAWN", tooltip = "Despawns the creature/gameobject within a given time (in milliseconds).", params = {{name = "Despawn Timer", tooltip = "Despawn Target in Milliseconds"}, {name = "Respawn Timer", tooltip = "Respawn in Seconds"}, {name = "Remove From World", tooltip = "0 = despawn, 1 = remove from world"}}, core = "timer"},
        [42] = {name = "SET_INVINCIBILITY_HP_LEVEL", tooltip = "Sets the creature's invincibility health to a flat value or percentage. Either one of the parameters must be set (so not both). Setting both to 0 will remove the effect.", params = {{name = "Flat value"}, {name = "% value"}}, core = "MinHpValue(+pct, -flat)"},
        [43] = {name = "MOUNT_TO_ENTRY_OR_MODEL", tooltip = "Sets the mount model to the model given in the second parameter (or takes the model of the entry given in the first parameter). Only one parameter may be used at the same time.", params = {{name = "CreatureId"}, {name = "ModelId"}}, core = "Creature_template entry(param1) OR ModelId (param2) (or 0 for both to dismount)"},
        [44] = {name = "SET_INGAME_PHASE_MASK", tooltip = "Sets the ACTUAL phasemask of the creature. This is not the event phasemask, but the actual phasemask. Sets the phasemask column in the creature table in the world database.", params = {{name = "Phasemask", tooltip = "creature.Phasemask"}}, core = "mask"},
        [45] = {name = "SET_DATA", tooltip = "Calls SMART_EVENT_DATA_SET with given field and data, making it possible to communicate between different entries.", params = {{name = "Field"}, {name = "Data"}}, core = "Field, Data (only creature @todo)"},
        [46] = {name = "ATTACK_STOP", tooltip = "Stop melee, spell casting during combat, chasing the target and facing"},
        [47] = {name = "SET_VISIBILITY", tooltip = "Sets the visibility of the creature or gameobject", params = {{name = "Visible", tooltip = "Makes creature Visible = 1 or Invisible = 0"}}, core = "on/off"},
        [48] = {name = "SET_ACTIVE", tooltip = "If a creature or GO is set active it will stay active even if no player is near. WARNING: keeping them active needs additional resources (CPU/RAM), the grid where the creature or object is located cannot be unloaded and other objects/creatures nearby also stay active", params = {{name = "Active", tooltip = "Can be 0 or 1"}}, core = "on/off"},
        [49] = {name = "ATTACK_START", tooltip = "Makes the creature start attacking the first unit it finds on the target list."},
        [50] = {name = "SUMMON_GO", tooltip = "Summon a gameobject entry. Use the Target to set the spawn position. If an entity is specified as target and also coordinates are set (target x,y,z), those coordinates are handled as offset from the target's position", params = {{name = "GameobjectId"}, {name = "DespawnTime", tooltip = "Despawn time in seconds"}, {name = "SummonTarget", tooltip = "If SummonTarget is 1, the target will summon the Gobject at the position of the actor"}, {name = "SummonType", tooltip = "0 - despawn after a specified time OR when the summoner dies, 1 - after a specified time"}}, core = "GameObjectID, DespawnTime in s"},
        [51] = {name = "KILL_UNIT", tooltip = "Kills the unit target instantly"},
        [52] = {name = "ACTIVATE_TAXI", tooltip = "Activates a taxipath of the given id for our (player) target.", params = {{name = "TaxiId"}}, core = "TaxiID"},
        [53] = {name = "WP_START", tooltip = "Starts a waypoint path from the `waypoint_data` table.", params = {{name = "Run", tooltip = "0 = walk. 1 = run. Unused, it is overridden by waypoint_data.move_type"}, {name = "PathId", tooltip = "waypoint_data.id"}, {name = "Repeat", tooltip = "Repeat the path when it's finished"}, {name = "QuestId", tooltip = "Quest entry to give credit for once the path has finished. Will use the target type and take all player entities from this list"}, {name = "DespawnTime", tooltip = "Time in milliseconds to wait after the path ended before we despawn. 0 = will not despawn"}}, core = "run/walk, pathID, canRepeat, quest, despawntime"},
        [54] = {name = "WP_PAUSE", tooltip = "Pauses the waypoint path the creature is currently following for a specific time (milliseconds).", params = {{name = "Time", tooltip = "Time in milliseconds"}}, core = "time"},
        [55] = {name = "WP_STOP", tooltip = "Stops the waypoint path the creature is currently following. Also allows you to specify a despawn time from that point on as well as which quest id should be counted as 'fail' (or not, based on the third parameter).", params = {{name = "DespawnTime", tooltip = "Time in milliseconds after which the creature despawns when the path was stopped"}, {name = "QuestId", tooltip = "Quest entry to count as 'failed' (based on third parameter). Does not have to be set if third parameter is set to 0."}, {name = "FailQuest", tooltip = "If set to 1, we will mark the quest in parameter 2 to failed for our player targets."}}, core = "despawnTime, quest, fail?"},
        [56] = {name = "ADD_ITEM", tooltip = "Adds item(s) to our player target.", params = {{name = "ItemId"}, {name = "Count"}}, core = "itemID, count"},
        [57] = {name = "REMOVE_ITEM", tooltip = "Removes item(s) from our player target.", params = {{name = "ItemId"}, {name = "Count"}}, core = "itemID, count"},
        [58] = {name = "INSTALL_AI_TEMPLATE", core = "UNUSED, DO NOT REUSE"},
        [59] = {name = "SET_RUN", tooltip = "Sets running flag on or off.", params = {{name = "On", tooltip = "0 = off. 1 = on"}}, core = "0/1"},
        [60] = {name = "SET_DISABLE_GRAVITY", tooltip = "Disables or enables gravity, making the creature hover in place.", params = {{name = "Disable", tooltip = "0 = gravity on. 1 = gravity off"}}, core = "0/1"},
        [61] = {name = "SET_SWIM", core = "UNUSED, DO NOT REUSE"},
        [62] = {name = "TELEPORT", tooltip = "Teleports the target to a specific map using coordinates in the target X/Y/Z/O fields. Note: May NOT use SMART_TARGET_POSITION (8)!", params = {{name = "MapId"}}, core = "mapID"},
        [63] = {name = "SET_COUNTER", tooltip = "Stores a decimal variable (number) under a variable id to store information for the creature during runtime. (The values set here can stack together compared to in Set Data).", params = {{name = "CounterId"}, {name = "Value"}, {name = "Reset", tooltip = "can be 0 or 1"}}, core = "id, value, reset (0/1)"},
        [64] = {name = "STORE_TARGET_LIST", tooltip = "Stores a list of targets under a variable id so it can later be read again.", params = {{name = "VarId"}}, core = "varID"},
        [65] = {name = "WP_RESUME", tooltip = "Resumes the waypoint path the creature was previously following.", core = "none"},
        [66] = {name = "SET_ORIENTATION", tooltip = "Used to alter the source's orientation. Depends on the script target. If SMART_TARGET_SELF, facing will be the same as in HomePosition, For SMART_TARGET_POSITION you need to set target_o : 0 = North, West = 1.5, South = 3, East = 4.5", params = {{name = "Quick Change", tooltip = "(0/1)"}, {name = "Random Orientation", tooltip = "(0/1)"}, {name = "Turning Angle", tooltip = "The value in degrees which will turn the creature counterclockwise. target_type must be NONE"}}},
        [67] = {name = "CREATE_TIMED_EVENT", tooltip = "Calls SMART_EVENT_UPDATE after a specific time with given parameters.", params = {{name = "EventId"}, {name = "InitialMin"}, {name = "InitialMax"}, {name = "RepeatMin", tooltip = "Set this ONLY if the event repeats"}, {name = "RepeatMax"}, {name = "Chance"}}, core = "id, InitialMin, InitialMax, RepeatMin(only if it repeats), RepeatMax(only if it repeats), chance"},
        [68] = {name = "PLAYMOVIE", tooltip = "Plays a movie of a given entry.", params = {{name = "MovieEntry"}}, core = "entry"},
        [69] = {name = "MOVE_TO_POS", tooltip = "PointId is called by SMART_EVENT_MOVEMENTINFORM. Continue this action with the TARGET_TYPE column. Use any target_type, and use target_x, target_y, target_z as the coordinates, if an entity is specified as target and also coordinates are set (target x,y,z) those coordinates are handled as offset from the target's position", params = {{name = "PointId", tooltip = "Can be used to call the MovementInform event"}, {name = "isTransport", tooltip = "0 or 1"}, {name = "isControlled", tooltip = "0 = aggro/threat will make it focus on player instead, 1 = Fixated to run to the xyzo position no matter what"}, {name = "Contact Distance", tooltip = "Absolute distance between the target and the source"}, {name = "Combat Reach", tooltip = "0/1 Uses CombatReach as the minimum distance between target and source. If ContactDistance > 0, then it will be added on top of CombatReach distance"}}, core = "PointId, transport, disablePathfinding, ContactDistance"},
        [70] = {name = "ENABLE_TEMP_GOBJ", tooltip = "Makes a temporarily disabled gameobject usable again for the given duration.", params = {{name = "Duration", tooltip = "Time in seconds"}}, core = "despawnTimer (sec)"},
        [71] = {name = "EQUIP", tooltip = "Set the creature's equipment template to a certain entry. If no entry (first parameter) is set, it will set the three item entries which are ordered by slot (param3 is main-hand, param4 is off-hand, param5 is gun/bow/etc). The slotmask (param2) value is 0 by default and goes by bits, so if it's '2' it will only show the off-hand weapon (bits are 1, 2 and 4). Having 0 defaults to 7, so all slots.", params = {{name = "EquipTemplateId", tooltip = "Entry of creature_equip_template. If left at 0, either parameter 3, 4 or 5 (or all, or just two) must be filled in with item entries to equip."}, {name = "Slotmask", tooltip = "Slotmask we show. Default is 0 and means all items are shown. If you only want to show one specific item (or two instead of all three), this field should be used as a bitmask starting at 1. Possible bits are 1, 2 and 4."}, {name = "ItemId 1", tooltip = "ItemId one (main hand slot) (only has use if the first parameter is 0)"}, {name = "ItemId 2", tooltip = "ItemId two (off hand slot) (only has use if the first parameter is 0)"}, {name = "ItemId 3", tooltip = "ItemId three (gun/bow/etc. slot) (only has use if the first parameter is 0)"}}, core = "entry, slotmask slot1, slot2, slot3 , only slots with mask set will be sent to client, bits are 1, 2, 4, leaving mask 0 is defaulted to mask 7 (send all), slots1-3 are only used if no entry is set"},
        [72] = {name = "CLOSE_GOSSIP", tooltip = "Closes the currently opened gossip to our player target.", core = "none"},
        [73] = {name = "TRIGGER_TIMED_EVENT", tooltip = "Calls SMART_EVENT_TIMED_EVENT_TRIGGERED with a given id.", params = {{name = "EventId"}}, core = "id(>1)"},
        [74] = {name = "REMOVE_TIMED_EVENT", tooltip = "Interrupts the timed event called from SMART_ACTION_TRIGGER_TIMED_EVENT. 0 is NOT a proper value!", params = {{name = "EventId"}}, core = "id(>1)"},
