        [80] = {name = "CALL_TIMED_ACTIONLIST", tooltip = "Calls a script for the source with a given entry.", params = {{name = "ScriptEntry", tooltip = "EntryOrGuid * 100 (entryorguid with 00 added after the entry, or 01, 02, 03 etc. for multiple action lists)"}, {name = "TimerType", tooltip = "The timer update type. If set to 0, the script will only occur out of combat. If set to 1, it will only occur during combat and if set to 2 it will always occur."}, {name = "allowOverride", tooltip = "0 - Must finish current actionlist, 1 - Allow starting new actionlist during previous actionlist"}}, core = "ID (overwrites already running actionlist), stop after combat?(0/1), timer update type(0-OOC, 1-IC, 2-ALWAYS)"},
        [81] = {name = "SET_NPC_FLAG", tooltip = "Set the npc flags of the target (using creature_template.npcflag)", params = {{name = "NpcFlags"}}, core = "Flags"},
        [82] = {name = "ADD_NPC_FLAG", tooltip = "Adds npc flags of the target (using creature_template.npcflag)", params = {{name = "NpcFlags"}}, core = "Flags"},
        [83] = {name = "REMOVE_NPC_FLAG", tooltip = "Removes npc flags of the target (using creature_template.npcflag)", params = {{name = "NpcFlags"}}, core = "Flags"},
        [84] = {name = "SIMPLE_TALK", tooltip = "Makes a player say text (just like SMART_ACTION_TALK, except that it makes the player target say it). Does NOT trigger SMART_EVENT_TEXT_OVER.", params = {{name = "GroupId", tooltip = "creature_text.GroupID"}}, core = "groupID, can be used to make players say groupID, Text_over event is not triggered, whisper can not be used (Target units will say the text)"},
        [85] = {name = "SELF_CAST", tooltip = "Make the target cast spell on it self", params = {{name = "SpellId"}, {name = "CastFlags", tooltip = "1 - Interrupt any spell casting. 2 - Triggered (this makes spell cost zero mana and have no cast time). 32 - Only casts the spell if the target does not have an aura from the spell"}, {name = "TriggerFlags"}, {name = "LimitTargets", tooltip = "0 = all targets"}}, core = "spellID, castFlags"},
        [86] = {name = "CROSS_CAST", tooltip = "Make the specified target type (in parameters) cast a spell to our target type", params = {{name = "SpellId"}, {name = "CastFlags"}, {name = "CasterTargetType", tooltip = "The caster is selected here, use it as target_type"}, {name = "CasterTarget1", tooltip = "target_param1"}, {name = "CasterTarget2", tooltip = "target_param2"}, {name = "CasterTarget3", tooltip = "target_param3"}}, core = "spellID, castFlags, CasterTargetType, CasterTarget param1, CasterTarget param2, CasterTarget param3, ( + the origonal target fields as Destination target), CasterTargets will cast spellID on all Targets (use with caution if targeting multiple * multiple units)"},
        [87] = {name = "CALL_RANDOM_TIMED_ACTIONLIST", tooltip = "Calls a random script for the source with given entries", params = {{name = "ScriptId 1", tooltip = "entryorguid * 100 + n"}, {name = "ScriptId 2", tooltip = "entryorguid * 100 + n"}, {name = "ScriptId 3", tooltip = "entryorguid * 100 + n"}, {name = "ScriptId 4", tooltip = "entryorguid * 100 + n"}, {name = "ScriptId 5", tooltip = "entryorguid * 100 + n"}, {name = "ScriptId 6", tooltip = "entryorguid * 100 + n"}}, core = "script9 ids 1-9"},
        [88] = {name = "CALL_RANDOM_RANGE_TIMED_ACTIONLIST", tooltip = "Calls a random script between two values for the source with given entries. So if parameter 1 is 500 and parameter 2 is 550, a script will randomly be picked between 500 and 550.", params = {{name = "ScriptId 1", tooltip = "entryorguid * 100 + n"}, {name = "ScriptId 2", tooltip = "entryorguid * 100 + n"}}, core = "script9 id min, max"},
