        [90] = {name = "SET_UNIT_FIELD_BYTES_1", tooltip = "Set the unit field bytes 1 flags of the target to a specific value", params = {{name = "UnitFieldBytes", tooltip = "See UnitStandStateType / UnitVisFlags in src/server/game/Entities/Unit/UnitDefines.h"}, {name = "Type", tooltip = "0 = targets the stand states (stand/sit/sleep/etc..). 1 = targets something talent-related for pets. 2 = targets the stand flags (creep/untrackable/etc..). 3 = targets the stand misc. flags (hover/always-stand/etc..)"}}, core = "bytes, target"},
