        [97] = {name = "JUMP_TO_POS", tooltip = "Jump to a given position with a given speed. Must use SMART_TARGET_SELF with this action_type. If selfJump is 1 the actor will jump to the target (you can add an offset from the target's position by also specifying target coordinates), if selfJump is 0 the targeted creature will jump to the target XYZO position. A speed value around 12 is normal speed", params = {{name = "Speed XY"}, {name = "Speed Z"}, {name = "SelfJump", tooltip = "0 or 1"}}, core = "speedXY, speedZ, targetX, targetY, targetZ"},
