        [101] = {name = "SET_HOME_POS", tooltip = "Sets the home position of the source to a new position. The home position is the position the creature runs to when evading/resetting/etc. Uses the target type to determine the new home position.", params = {{name = "FromDB", tooltip = "0: if the target is a creature, set it's current position as it's new home position, if the target is SMART_TARGET_POSITION, use this position as new home position for the actor 1: if the target is a creature, reset it's home position to the one from the DB, if the target is SMART_TARGET_POSITION, reset the actor's home position to the one from the DB (the actual values of the target position are ignored)"}}, core = "none"},
